/* The home page is an interactive room; the existing store remains on its own pages. */
window.initShadesHero=function(){
 document.body.classList.add('archive-home');
 const products=P.filter(p=>p.archive),reduced=matchMedia('(prefers-reduced-motion: reduce)');let stage=null,entering=false,opened=null,busy=false,lastFocus=null,active=-1;
 document.querySelector('#header').innerHTML=`<button class="archive-back" aria-label="Return to showroom introduction"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m13 5-7 7 7 7M6 12h15"/></svg><span>back</span></button><div class="archive-nav"><button id="archive-menu" aria-haspopup="dialog">menu</button><a href="cart.html" id="bag-icon" aria-label="Shopping bag">//cart <span id="bag-count">${count()}</span></a></div>`;
 document.querySelector('#main').innerHTML=`<section class="archive-room" aria-label="SHADES interactive menswear showroom"><canvas id="archive-canvas" aria-label="A three-dimensional chrome clothing rack in a monochrome studio"></canvas><div class="archive-intro"><p class="archive-overline">CONTEMPORARY<br>MENSWEAR ARCHIVE</p><div class="archive-brand"><h1>shades.<sup>®</sup></h1><span class="archive-sticker">A DIFFERENT<br>PERSPECTIVE / 01</span></div><p class="archive-intro-note">Curated pieces.<br>Considered presence.</p><button id="archive-enter" disabled>Preparing the room<span class="archive-loading" aria-hidden="true"></span></button><span class="archive-origin">SHADES / COIMBATORE</span></div><div class="archive-showroom-ui" inert><h2 class="archive-category">man / clothing</h2><button class="archive-hover-label" id="archive-hover" hidden></button><p class="archive-instruction">Drag the rail · hover to explore · click to inspect</p><nav class="archive-categories" aria-label="Showroom categories"><a href="shop.html">Store</a><button data-archive-filter="all" class="is-active" aria-pressed="true">Man</button><button data-archive-filter="layers" aria-pressed="false">Layers</button></nav><div class="archive-piece-access" aria-label="Choose an archive piece">${products.map((p,i)=>`<button data-archive-piece="${i}">Inspect ${p.name}</button>`).join('')}</div></div><p id="archive-status" class="sr-only" role="status"></p><div class="archive-fallback" hidden><p>The 3D showroom is unavailable in this browser.</p><a href="shop.html">Explore the collection</a></div></section>`;
 const room=document.querySelector('.archive-room'),intro=room.querySelector('.archive-intro'),ui=room.querySelector('.archive-showroom-ui'),label=room.querySelector('#archive-hover'),enter=room.querySelector('#archive-enter'),status=room.querySelector('#archive-status');
 const touch=matchMedia('(pointer: coarse), (max-width: 760px)'),instruction=()=>room.querySelector('.archive-instruction').textContent=touch.matches?'Swipe to browse · tap a piece, then tap again to inspect':'Drag the rail · hover to explore · click to inspect';instruction();touch.addEventListener('change',instruction);
 const menu=document.createElement('dialog');menu.className='archive-menu-dialog';menu.setAttribute('aria-label','SHADES menu');menu.innerHTML=`<button class="archive-menu-close" aria-label="Close menu">Close ×</button><span>SHADES / INDEX</span><nav aria-label="Site pages"><a href="shop.html">The collection</a><a href="collections.html">Collections</a><a href="runway.html">Fashion Runway</a><a href="lookbook.html">The edit</a><a href="about.html">Our story</a><a href="account.html">Your account</a></nav><small>CONTEMPORARY MENSWEAR / COIMBATORE</small>`;document.body.append(menu);
 document.querySelector('#archive-menu').onclick=()=>menu.showModal();menu.querySelector('button').onclick=()=>menu.close();
 const detail=document.createElement('dialog');detail.className='archive-product';detail.setAttribute('aria-labelledby','archive-product-name');document.body.append(detail);
 function showHover(index,point){active=index;if(index<0||opened||!entering){label.hidden=true;return;}label.textContent=products[index].name.toUpperCase();label.hidden=false;label.style.left=point.x+'px';label.style.top=point.y+'px';}
 function hoverPosition(point){if(!label.hidden){label.style.left=point.x+'px';label.style.top=point.y+'px';}}
 function closeDetail(){if(!detail.open||busy)return;detail.close();opened=null;room.inert=false;stage?.closeProduct();document.body.classList.remove('archive-inspecting');lastFocus?.focus({preventScroll:true});}
 function selectProduct(index){if(!stage||opened||!entering)return;const p=products[index];opened=p;lastFocus=document.activeElement;label.hidden=true;stage.selectProduct(index);room.inert=true;document.body.classList.add('archive-inspecting');
  detail.innerHTML=`<button class="archive-detail-close" aria-label="Return to clothing rack">Back to rack</button><section class="archive-product-info"><span class="archive-drop">SHADES / ARCHIVE DROP 01</span><h2 id="archive-product-name">${p.name}</h2><p>${p.description}</p><div class="archive-product-price">${money(p.price)}</div><div class="archive-product-color"><i style="background:${p.swatch}" aria-hidden="true"></i>${p.color} / ${p.fabric}</div><form id="archive-add"><fieldset><legend>SIZE</legend><div class="archive-sizes">${p.sizes.map(size=>`<label><input type="radio" required name="size" value="${size}"><span>${size}</span></label>`).join('')}</div></fieldset><button class="archive-add" type="submit">ADD TO CART</button><p class="archive-add-status" role="status"></p></form><div class="archive-detail-links"><a href="${url(p)}">Full product details</a><a href="cart.html">View cart</a></div><p class="archive-product-note">Sample archive · No payment is taken.</p></section><div class="archive-fold-origin" aria-hidden="true"></div>`;
  detail.showModal();stage.setDetailOrigin(detail.querySelector('.archive-fold-origin'));
  detail.querySelector('.archive-detail-close').onclick=closeDetail;
  detail.querySelector('form').onsubmit=async e=>{e.preventDefault();if(busy)return;const size=new FormData(e.target).get('size');if(!p.sizes.includes(size))return;busy=true;const button=detail.querySelector('.archive-add'),message=detail.querySelector('.archive-add-status'),back=detail.querySelector('.archive-detail-close');button.disabled=true;back.disabled=true;detail.setAttribute('aria-busy','true');button.innerHTML='<i class="archive-spinner" aria-hidden="true"></i> ADDING…';message.textContent='Preparing your selection.';
   try{stage.hideSelected(true);await window.addHeroToBag(p,size,detail.querySelector('.archive-fold-origin'));button.textContent='ADDED';message.innerHTML='Added to your cart. <a href="cart.html">View cart</a>';}catch{button.textContent='ADD TO CART';message.textContent='Unable to add this piece. Please try again.';}finally{stage.hideSelected(false);busy=false;button.disabled=false;back.disabled=false;detail.removeAttribute('aria-busy');}
  };
 }
 detail.addEventListener('cancel',e=>{e.preventDefault();closeDetail()});
 function enterRoom(){if(!stage||entering)return;entering=true;room.classList.add('is-entered');ui.inert=false;intro.inert=true;document.querySelector('.archive-back').setAttribute('aria-label','Return to showroom introduction');stage.enter();status.textContent='Menswear showroom. Eight archive pieces. Drag to browse, or use the piece selection buttons.';}
 function returnIntro(){if(detail.open){closeDetail();return;}if(!stage)return;entering=false;room.classList.remove('is-entered');ui.inert=true;intro.inert=false;label.hidden=true;stage.introduction();enter.focus({preventScroll:true});}
 document.querySelector('.archive-back').onclick=returnIntro;enter.onclick=enterRoom;label.onclick=()=>{if(active>=0)selectProduct(active)};
 room.querySelectorAll('[data-archive-piece]').forEach(button=>{button.onfocus=()=>{if(entering)stage?.focusPiece(Number(button.dataset.archivePiece))};button.onclick=()=>selectProduct(Number(button.dataset.archivePiece));});
 room.querySelectorAll('[data-archive-filter]').forEach(button=>button.onclick=()=>{room.querySelectorAll('[data-archive-filter]').forEach(b=>{b.classList.toggle('is-active',b===button);b.setAttribute('aria-pressed',String(b===button))});stage?.filter(button.dataset.archiveFilter);status.textContent=button.dataset.archiveFilter==='layers'?'Showing jackets and hoodies.':'Showing all eight archive pieces.';});
 import('./archive-scene.mjs?v=6').then(async({createArchiveStage})=>{stage=await createArchiveStage({canvas:room.querySelector('canvas'),products,onHover:showHover,onHoverPosition:hoverPosition,onSelect:selectProduct,reduced});enter.disabled=false;enter.textContent='Enter showroom';room.classList.add('is-ready');if(reduced.matches)enterRoom();else window.setTimeout(()=>{if(!entering&&!menu.open)enterRoom()},1900);}).catch(error=>{console.error('SHADES showroom:',error);room.classList.add('scene-unavailable');intro.hidden=true;room.querySelector('.archive-fallback').hidden=false;});
};
